import type { ToolResult } from "../../types.js";

// Shared domain types for the plugin-creation workflow.
export type PluginComplexityTier = "simple" | "medium" | "large";
export type MavenDependencyScope = "provided" | "compile" | "runtime";

// These match the dependency and repository objects generated by the plugin coders
// and later consumed by the plugin build tool.
export type MavenDependency = {
  groupId: string;
  artifactId: string;
  version: string;
  scope: MavenDependencyScope;
};

export type MavenRepository = {
  id: string;
  url: string;
};

export type PluginProjectFile = {
  path: string;
  content: string;
};

// Edit coders receive existing files as numbered lines so they can describe precise edits.
export type PluginLineObject = {
  line: number;
  content: string;
};

export type PluginProjectFileLines = {
  file: string;
  lines: PluginLineObject[];
};

export type PluginProjectManifest = {
  description: string;
  javaFiles: PluginProjectFile[];
  resourceFiles: PluginProjectFile[];
  dependencies: MavenDependency[];
  repositories: MavenRepository[];
};

// Medium-plugin follow-up tasks return an edit plan instead of a full project rewrite.
export type PluginFileDeletion = {
  file: string;
  startLine: number;
  endLine: number;
};

export type PluginFileInsertion = {
  file: string;
  startLine: number;
  content: string;
};

export type PluginEditPlan = {
  description: string;
  deletions: PluginFileDeletion[];
  insertions: PluginFileInsertion[];
  newJavaFiles: PluginProjectFile[];
  newResourceFiles: PluginProjectFile[];
  dependencies: MavenDependency[];
  repositories: MavenRepository[];
};

export type PluginTask = {
  id: number;
  title: string;
  description: string;
  dependencies: MavenDependency[];
  repositories: MavenRepository[];
};

export type PluginRequestMessage = {
  intent: string;
  summary: string;
  requirements: string[];
};

export type PluginCreationRequest = {
  pluginName: string;
  assistantMessage: PluginRequestMessage;
};

export type PluginComplexityDecision = {
  tier: PluginComplexityTier;
};

export type PluginReview = {
  summary: string;
  commands: string[];
  permissions: string[];
  notes: string[];
};

export type BuiltPluginArtifact = {
  file: `${string}.jar`;
  version: string;
};

// This is the final success payload sent back to the calling agent.
export type PluginPipelineSuccess = {
  pluginName: string;
  version: string;
  file: `${string}.jar`;
  summary: string;
  complexityScore: number;
  complexityTier: PluginComplexityTier;
};

export type PluginPipelineErrorCode =
  | "ALREADY_EXISTS"
  | "IMPOSSIBLE"
  | "LARGE_UNSUPPORTED"
  | "BUILD_FAILED"
  | "INTERNAL_ERROR";

export type PluginPipelineError = {
  code: PluginPipelineErrorCode;
  message: string;
  complexityScore?: number;
  complexityTier?: PluginComplexityTier;
  details?: string;
};

export type PluginPipelineResult = ToolResult<PluginPipelineSuccess, PluginPipelineError>;

export type PluginBuildErrorCode = "ALREADY_EXISTS" | "BUILD_FAILED" | "GITHUB_FAILED";

export type PluginBuildError = {
  code: PluginBuildErrorCode;
  message: string;
  details?: string;
};

export type PluginBuildResult = ToolResult<BuiltPluginArtifact, PluginBuildError>;

// Individual plugin specialists each return a ToolResult so the pipeline can
// handle model failures and invalid responses consistently.
export type PluginArchitectResult = ToolResult<
  PluginTask[],
  {
    code: "IMPOSSIBLE" | "INVALID_RESPONSE";
    message: string;
  }
>;

export type PluginCoderResult = ToolResult<
  PluginProjectManifest,
  {
    code: "INVALID_RESPONSE";
    message: string;
  }
>;

export type PluginEditCoderResult = ToolResult<
  PluginEditPlan,
  {
    code: "INVALID_RESPONSE";
    message: string;
  }
>;

export type PluginReviewerResult = ToolResult<
  PluginReview,
  {
    code: "INVALID_RESPONSE";
    message: string;
  }
>;
